theorem _root_.Matrix.PosDef.quadForm_pos {A : Matrix n n 𝕜} (hA : A.PosDef) {z : n → 𝕜}
    (hz : z ≠ 0) :
    0 < quadForm A z

theorem frobInner_mul_left_of_orthonormal [DecidableEq p] {Q : Matrix m p 𝕜}
    (hQ : Qᴴ * Q = 1) (X Y : Matrix p n 𝕜) :
    frobInner (Q * X) (Q * Y) = frobInner X Y

theorem specNorm_conjTranspose_mul_of_eq_mul [DecidableEq p] {P : Matrix m n 𝕜}
    (hP : Pᴴ * P = 1) {X : Matrix m p 𝕜} (hX : X = P * (Pᴴ * X)) :
    specNorm (Pᴴ * X) = specNorm X

theorem specNorm_mul_left_of_hasOrthonormalCols {𝕜 : Type*} [RCLike 𝕜] {p : Type*}
    [Fintype p] [DecidableEq p] {P : Matrix m n 𝕜} (hP : HasOrthonormalCols P)
    (A : Matrix n p 𝕜) : specNorm (P * A) = specNorm A

theorem _root_.Matrix.IsHermitian.eigenvalues₀_congr [DecidableEq n] {A B : Matrix n n 𝕜}
    (hA : A.IsHermitian) (hB : B.IsHermitian) (h : A = B) (i : Fin (Fintype.card n)) :
    hA.eigenvalues₀ i = hB.eigenvalues₀ i

theorem lambdaMin_eq_eigenvalues₀_last [DecidableEq n] [Nonempty n] {A : Matrix n n 𝕜}
    (hA : A.IsHermitian) :
    lambdaMin A = hA.eigenvalues₀ ⟨Fintype.card n - 1, Nat.sub_one_lt_of_lt Fintype.card_pos⟩

theorem posSemidef_fromBlocks_diag {R : Type*} [CommRing R] [PartialOrder R] [StarRing R]
    [StarOrderedRing R] {P : Matrix m m R} {Q : Matrix n n R}
    (hP : P.PosSemidef) (hQ : Q.PosSemidef) : (fromBlocks P 0 0 Q).PosSemidef

theorem cfc_reindex_of_isHermitian {n : Type*} [Fintype n] [DecidableEq n] {r : Type*}
    [Fintype r] [DecidableEq r] (e : n ≃ r) (f : ℝ → ℝ) (A : Matrix n n ℂ) (hA : A.IsHermitian) :
    cfc f (Matrix.reindex e e A) = Matrix.reindex e e (cfc f A)

theorem matrixComplexPower_eq_matrixExp_smul_log {A : Matrix n n ℂ}
    (hA : A.PosDef) (z : ℂ) :
    matrixComplexPower A z = matrixExp (z • matrixLog A)

theorem matrixComplexPower_ofReal_eq_rpow {A : Matrix n n ℂ}
    (hA : A.PosSemidef) (r : ℝ) :
    matrixComplexPower A (r : ℂ) = CFC.rpow A r

theorem norm_matrixComplexPower_le_of_re_eq_one {A : Matrix n n ℂ}
    (hA : A.PosSemidef) {z : ℂ} (hz : z.re = 1) :
    ‖matrixComplexPower A z‖ ≤ ‖A‖

theorem continuousOn_comp_joukowski_closed_annulus {F : ℂ → ℂ} {ρ : ℝ}
    (hF : ContinuousOn F (filledBernsteinEllipse ρ)) :
    ContinuousOn (F ∘ joukowski) (closedBall (0 : ℂ) ρ \ ball 0 1)

theorem filledBernsteinEllipse_subset_openBernsteinEllipse {r ρ : ℝ}
    (hρ : 1 < ρ) (hrρ : r < ρ) :
    filledBernsteinEllipse r ⊆ openBernsteinEllipse ρ

theorem abs_chebyshevCoeff_le_two_mul {f : ℝ → ℝ} {M : ℝ}
    (hM : ∀ x ∈ Icc (-1 : ℝ) 1, |f x| ≤ M) {k : ℕ} (hk : 0 < k) :
    |chebyshevCoeff f k| ≤ 2 * M

theorem chebyshevCoeff_add {f g : ℝ → ℝ}
    (hf : ContinuousOn f (Icc (-1 : ℝ) 1)) (hg : ContinuousOn g (Icc (-1 : ℝ) 1))
    (k : ℕ) : chebyshevCoeff (fun x => f x + g x) k = chebyshevCoeff f k + chebyshevCoeff g k

theorem chebyshevCoeff_sub {f g : ℝ → ℝ}
    (hf : ContinuousOn f (Icc (-1 : ℝ) 1)) (hg : ContinuousOn g (Icc (-1 : ℝ) 1))
    (k : ℕ) : chebyshevCoeff (fun x => f x - g x) k = chebyshevCoeff f k - chebyshevCoeff g k

theorem abs_tensorChebyshevCosinePartial_le {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) (θ : Fin (d + 1) → ℝ) :
    |tensorChebyshevCosinePartial f i θ| ≤ L * |sin (θ i)|

theorem abs_tensorChebyshevCosinePartial_le_const {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) (θ : Fin (d + 1) → ℝ) :
    |tensorChebyshevCosinePartial f i θ| ≤ L

theorem integrable_tensorChebyshevCosinePartial_mul_mixed {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) (α : Fin (d + 1) → ℕ) :
    Integrable (fun θ => tensorChebyshevCosinePartial f i θ * tensorChebyshevMixedBasis i α θ)
      (Measure.pi (fun _ => chebyshevAngleMeasure))

theorem integrable_tensorChebyshevCosinePartial_sq {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) :
    Integrable (fun θ => tensorChebyshevCosinePartial f i θ ^ 2)
      (Measure.pi (fun _ => chebyshevAngleMeasure))

theorem integral_tensorChebyshevCosinePartial_mul_mixed_eq {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) (α : Fin (d + 1) → ℕ) (hα : 0 < α i) :
    (∫ θ, tensorChebyshevCosinePartial f i θ * tensorChebyshevMixedBasis i α θ
      ∂Measure.pi (fun _ => chebyshevAngleMeasure)) = (α i : ℝ) * tensorChebyshevCoeff f α

theorem integral_tensorChebyshevCosinePartial_sq_le {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) :
    (∫ θ, tensorChebyshevCosinePartial f i θ ^ 2
      ∂Measure.pi (fun _ => chebyshevAngleMeasure)) ≤ π ^ (d + 1) * (L : ℝ) ^ 2 / 2

theorem lipschitzWith_euclidean_insertNth {d : ℕ} {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ}
    {L : NNReal} (hf : LipschitzWith L f) (i : Fin (d + 1)) (y : Fin d → ℝ) :
    LipschitzWith L (fun t : ℝ => f (WithLp.toLp 2 (i.insertNth t y)))

theorem measurable_tensorChebyshevCosinePartial {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} (hf : Continuous f) (i : Fin (d + 1)) :
    Measurable (tensorChebyshevCosinePartial f i)

theorem sum_coordinate_sq_mul_tensorChebyshevCoeff_sq_le {d : ℕ}
    {f : EuclideanSpace ℝ (Fin (d + 1)) → ℝ} {L : NNReal}
    (hf : LipschitzWith L f) (i : Fin (d + 1)) (s : Finset (Fin (d + 1) → ℕ)) :
    (∑ α ∈ s, (α i : ℝ) ^ 2 * tensorChebyshevCoeff f α ^ 2) ≤
      π ^ (d + 1) * (L : ℝ) ^ 2 / 2

theorem summable_norm_sq_mul_tensorChebyshevCoeff_sq_of_lipschitzWith {d : ℕ}
    {f : EuclideanSpace ℝ (Fin d) → ℝ} {L : NNReal} (hf : LipschitzWith L f) :
    Summable (fun α : Fin d → ℕ => (∑ i, (α i : ℝ) ^ 2) * tensorChebyshevCoeff f α ^ 2)

theorem tsum_norm_sq_mul_tensorChebyshevCoeff_sq_le_of_lipschitzOnWith {d : ℕ}
    {f : EuclideanSpace ℝ (Fin d) → ℝ} {L : NNReal}
    (hf : LipschitzOnWith L f (chebyshevCube (Fin d))) :
    (∑' α : Fin d → ℕ, (∑ i, (α i : ℝ) ^ 2) * tensorChebyshevCoeff f α ^ 2) ≤
      (d : ℝ) * π ^ d * (L : ℝ) ^ 2 / 2

theorem ae_mem_chebyshevCube_normalCoordinateSpectralLaw {A : Matrix n n ℂ}
    (hA : A * Aᴴ = Aᴴ * A) (b : n → ℂ) (hbound : specNorm A ≤ 1) :
    ∀ᵐ x ∂normalCoordinateSpectralLaw hA b, x ∈ chebyshevCube (Fin 2)

theorem isProbabilityMeasure_normalCoordinateSpectralLaw {A : Matrix n n ℂ}
    (hA : A * Aᴴ = Aᴴ * A) (b : n → ℂ) (hb : ‖WithLp.toLp 2 b‖ = 1) :
    IsProbabilityMeasure (normalCoordinateSpectralLaw hA b)

theorem ae_norm_le_normalEmpiricalSpectralLaw {A : Matrix n n ℂ}
    (hA : A*Aᴴ = Aᴴ*A) :
    ∀ᵐ z ∂normalEmpiricalSpectralLaw hA, ‖z‖ ≤ specNorm A

theorem integral_normalEmpiricalSpectralLaw_eq_trace_cfc {A : Matrix n n ℂ}
    (hA : A*Aᴴ = Aᴴ*A) (f : ℂ → ℂ) :
    ∫ z, f z ∂normalEmpiricalSpectralLaw hA = (cfc f A).trace/(Fintype.card n : ℂ)

theorem run_hermitianPartScalarProgram (imaginary : Bool) (y z : ℂ) :
    (hermitianPartScalarProgram imaginary y z).run =
      if imaginary then (-Complex.I/2)*(y-z) else (1/2:ℂ)*(y+z)

theorem run_eq_of_forall_apply_queries_eq (alg : QueryAlgorithm Q R q β) {f g : Q → R}
    (h : ∀ j, g (alg.queries (alg.transcript f) j) = f (alg.queries (alg.transcript f) j)) :
    alg.run g = alg.run f

theorem transcript_eq_of_forall_apply_queries_eq (alg : QueryAlgorithm Q R q β) {f g : Q → R}
    (h : ∀ j, g (alg.queries (alg.transcript f) j) = f (alg.queries (alg.transcript f) j)) :
    alg.transcript g = alg.transcript f

theorem counts_of_mem_subInsertionWords {w : List Bool} {v : ℕ × List Bool}
    (hv : v ∈ subInsertionWords w) :
    v.2.count false = w.count false ∧ v.2.count true + v.1 = w.count true

theorem degree_sub_lt_of_monic_natDegree_eq {p q : ℝ[X]} {n : ℕ}
    (hp : p.Monic) (hq : q.Monic) (hpn : p.natDegree = n)
    (hqn : q.natDegree = n) : (p - q).degree < n

theorem sum_eval_mul_nodalWeight_eq_zero {n : ℕ} {v : Fin (n + 1) → ℝ}
    (hv : Function.Injective v) {p : Polynomial ℝ} (hp : p.degree < n) :
    (∑ i, p.eval (v i) * Lagrange.nodalWeight univ v i) = 0

theorem eval_nodal_in_gap_ne_zero {n : ℕ} {v : Fin (n + 2) → ℝ}
    (hv : StrictMono v) (i : Fin (n + 1)) {x : ℝ} (hx : x ∈ Ioo (v i.castSucc) (v i.succ)) :
    (Lagrange.nodal univ v).eval x ≠ 0

theorem signed_eval_nodal_in_gap_pos {n : ℕ} {v : Fin (n + 2) → ℝ}
    (hv : StrictMono v) (i : Fin (n + 1)) {x : ℝ} (hx : x ∈ Ioo (v i.castSucc) (v i.succ)) :
    0 < (-1 : ℝ) ^ (n + 1 - i.val) * (Lagrange.nodal univ v).eval x

theorem eval_pos_of_coeff_nonneg_of_coeff_zero_pos {p : ℝ[X]}
    (hp : ∀ k, 0 ≤ p.coeff k) (hp0 : 0 < p.coeff 0) {x : ℝ} (hx : 0 ≤ x) :
    0 < p.eval x

theorem inv_sub_eval_geometricResolventPolynomial_eq {z t : 𝕜}
    (hz : z ≠ 0) (hzt : z ≠ t) (m : ℕ) :
    (z-t)⁻¹ - (geometricResolventPolynomial z m).eval t = t^m/(z^m*(z-t))

theorem AlgHom.map_resolvent (φ : A →ₐ[R] B) {a : A} {z : R}
    (hz : z ∈ resolventSet R a) :
    φ (resolvent a z) = resolvent (φ a) z

theorem IsSelfAdjoint.isUnit_algebraMap_sub_of_im_ne_zero {a : A}
    (ha : IsSelfAdjoint a) {z : ℂ} (hz : z.im ≠ 0) :
    IsUnit (algebraMap ℂ A z - a)

theorem IsSelfAdjoint.resolvent_eq_cfc_of_im_ne_zero {a : A}
    (ha : IsSelfAdjoint a) {z : ℂ} (hz : z.im ≠ 0) :
    resolvent a z = cfc (fun x : ℂ => (z - x)⁻¹) a

theorem norm_resolvent_sub_resolvent_le_projected {a b p : A} {z : R}
    (ha : z ∈ resolventSet R a) (hb : z ∈ resolventSet R b)
    (hp : p * p = p) {c : R}
    (hab : a - b = c • p) :
    ‖resolvent a z - resolvent b z‖ ≤
      ‖c‖ * (‖resolvent a z * p‖ * ‖p * resolvent b z‖)

theorem IsSelfAdjoint.exists_mem_spectrum_real_dist_le_norm_sub {a b : A}
    (ha : IsSelfAdjoint a) {x : ℝ} (hxb : x ∈ spectrum ℝ b) :
    ∃ y ∈ spectrum ℝ a, dist x y ≤ ‖a - b‖

theorem IsStarNormal.exists_mem_spectrum_dist_le_norm_sub {a b : A}
    (ha : IsStarNormal a) {z : ℂ} (hzb : z ∈ spectrum ℂ b) :
    ∃ w ∈ spectrum ℂ a, dist z w ≤ ‖a - b‖

theorem IsStarNormal.resolvent_eq_cfc_of_notMem_spectrum {a : A}
    (ha : IsStarNormal a) {z : ℂ} (hz : z ∉ spectrum ℂ a) :
    resolvent a z = cfc (fun x : ℂ => (z - x)⁻¹) a

theorem PositiveLinearMap.re_mul_nonneg_of_tracial (φ : A →ₚ[ℂ] ℂ)
    (htrace : ∀ x y : A, φ (x * y) = φ (y * x)) {a b : A}
    (ha : 0 ≤ a) (hb : 0 ≤ b) : 0 ≤ (φ (a * b)).re

theorem HasCoeffDerivAt.mul {p q : ℝ → ℝ[X]} {p' q' : ℝ[X]} {x : ℝ}
    (hp : HasCoeffDerivAt p p' x) (hq : HasCoeffDerivAt q q' x) :
    HasCoeffDerivAt (fun y => p y * q y) (p' * q x + p x * q') x

theorem continuousAt_coeff_prod {ι : Type*} (s : Finset ι) {p : ι → T → R[X]}
    (hp : ∀ i ∈ s, ∀ k, ContinuousAt (fun y => (p i y).coeff k) a) (k : ℕ) :
    ContinuousAt (fun y => (∏ i ∈ s, p i y).coeff k) a

theorem continuousAt_coeff_basisDivisor {u v : E → 𝕜}
    (hu : ContinuousAt u a) (hv : ContinuousAt v a) (hne : u a ≠ v a) (k : ℕ) :
    ContinuousAt (fun y => (basisDivisor (u y) (v y)).coeff k) a

theorem ContDiff.sub_eq_integral_fderiv_segment {f : E → F}
    (hf : ContDiff ℝ 1 f) (x h : E) :
    f (x + h) - f x = ∫ u in (0 : ℝ)..1, fderiv ℝ f (x + u • h) h

theorem bottom_succ_eq_top {g : ℂ → ℂ} {ψ : ℝ × ℝ → ℂ}
    (D : PrimitiveHomotopyGrid g ψ) (hψ : Continuous ψ) {i j : ℕ}
    (hi : i < D.size) (hj : j + 1 < D.size) : D.bottom i (j + 1) = D.top i j

theorem left_succ_eq_right {g : ℂ → ℂ} {ψ : ℝ × ℝ → ℂ}
    (D : PrimitiveHomotopyGrid g ψ) (hψ : Continuous ψ) {i j : ℕ}
    (hi : i + 1 < D.size) (hj : j < D.size) : D.left (i + 1) j = D.right i j

theorem neg_abs_sin_mul_norm_le_im_exp_mul {θ : ℝ} {z : ℂ}
    (hcos : 0 ≤ Real.cos θ) (hz : 0 ≤ z.im) :
    -(|Real.sin θ| * ‖z‖) ≤ (exp (θ * I) * z).im

theorem ellipseMap_mem_off_real_or_exterior {M ε R θ : ℝ}
    (hM : 0 < M) (hε : 0 < ε) (hRM : R < M) :
    (ellipseMap M ε θ).im ≠ 0 ∨ R < ‖ellipseMap M ε θ‖

theorem primitivePathIntegral_refl {a : ℂ} {g : ℂ → ℂ}
    (h : Nonempty (PrimitivePathSubdivision g (Path.refl a).extend)) :
    primitivePathIntegral g (Path.refl a) h = 0

theorem cubicalPrimitiveIntegral_boundaryTwo {Ω : Set ℂ}
    {g : ℂ → ℂ} (hΩ : IsOpen Ω) (hg : DifferentiableOn ℂ g Ω) (S : Cubical.TwoChain Ω) :
    cubicalPrimitiveIntegral g hΩ hg (Cubical.boundaryTwo S) = 0

theorem cubicalPrimitiveIntegral_constantChain {Ω : Set ℂ}
    {g : ℂ → ℂ} (hΩ : IsOpen Ω) (hg : DifferentiableOn ℂ g Ω) (D : Ω →₀ ℤ) :
    cubicalPrimitiveIntegral g hΩ hg (Cubical.constantChain D) = 0

theorem cubicalPrimitiveIntegral_squareBoundary {Ω : Set ℂ}
    {g : ℂ → ℂ} (hΩ : IsOpen Ω) (hg : DifferentiableOn ℂ g Ω) (q : C(I × I, Ω)) :
    cubicalPrimitiveIntegral g hΩ hg (Cubical.squareBoundary q) = 0

theorem cubicalCurveIntegral_const_mul {Ω : Set ℂ}
    (Γ : Cubical.OneChain Ω) (c : ℂ) (g : ℂ → ℂ) :
    cubicalCurveIntegral (fun z => c * g z) Γ = c * cubicalCurveIntegral g Γ

theorem norm_cubicalCurveIntegral_le_length_mul {Ω : Set ℂ}
    (Γ : Cubical.OneChain Ω) (g : ℂ → ℂ) {C : ℝ}
    (hΓ : ∀ γ ∈ Γ.support, ContDiffOn ℝ 1 (cubicalPath γ).extend I)
    (hg : ∀ γ ∈ Γ.support, ∀ r, ‖g (γ r : ℂ)‖ ≤ C) :
    ‖cubicalCurveIntegral g Γ‖ ≤ cubicalLength Γ * C

theorem norm_two_pi_i_inv_mul_cubicalCurveIntegral_le_length_mul {Ω : Set ℂ}
    (Γ : Cubical.OneChain Ω) (g : ℂ → ℂ) {C : ℝ}
    (hΓ : ∀ γ ∈ Γ.support, ContDiffOn ℝ 1 (cubicalPath γ).extend I)
    (hg : ∀ γ ∈ Γ.support, ∀ r, ‖g (γ r : ℂ)‖ ≤ C) :
    ‖(2 * Real.pi * Complex.I : ℂ)⁻¹ * cubicalCurveIntegral g Γ‖ ≤
      cubicalLength Γ / (2 * Real.pi) * C

theorem isBounded_cubicalWindingIntegral_level_of_ne_zero {Ω : Set ℂ}
    (Γ : Cubical.OneChain Ω)
    (hΓ : ∀ γ ∈ Γ.support, ContDiffOn ℝ 1 (cubicalPath γ).extend I)
    {w : ℂ} (hw : w ≠ 0) : Bornology.IsBounded {v : ℂ | cubicalWindingIntegral Γ v = w}

theorem boundedComplementFill_subset_closedBall {s : Set E} {R : ℝ}
    (hR : 0 ≤ R) (hs : s ⊆ closedBall 0 R) :
    boundedComplementFill s ⊆ closedBall 0 R

theorem connectedComponentIn_subset_compl_boundedComplementFill {s : Set X} {x : X}
    (hx : x ∉ boundedComplementFill s) :
    connectedComponentIn sᶜ x ⊆ (boundedComplementFill s)ᶜ

theorem norm_cell_sub_cell_le {m n : ℕ}
    (x : Fin (m + 1) → ℝ) (y : Fin (n + 1) → ℝ)
    (hx : Monotone x) (hy : Monotone y) (i : Fin m) (j : Fin n) {h : ℝ}
    (hwidth : x i.succ - x i.castSucc ≤ h) (hheight : y j.succ - y j.castSucc ≤ h)
    (p q : I × I) : ‖Grid.cell (vertex x y) i j p - Grid.cell (vertex x y) i j q‖ ≤ 2 * h

theorem norm_cell_sub_center_le {m n : ℕ}
    (x : Fin (m + 1) → ℝ) (y : Fin (n + 1) → ℝ)
    (hx : Monotone x) (hy : Monotone y) (i : Fin m) (j : Fin n) {h : ℝ}
    (hwidth : x i.succ - x i.castSucc ≤ h) (hheight : y j.succ - y j.castSucc ≤ h)
    (p : I × I) : ‖Grid.cell (vertex x y) i j p - center x y i j‖ ≤ h

theorem partialSum_sub {A : Type*} [AddCommGroup A] {n : ℕ}
    (f g : Fin n → A) (i : Fin (n + 1)) :
    partialSum (fun j => f j - g j) i = partialSum f i - partialSum g i

theorem forall_mem_concat (p : Fin (n + 1) → E)
    (γ : (i : Fin n) → Path (p i.castSucc) (p i.succ)) {s : Set E}
    (hp : p 0 ∈ s) (hγ : ∀ i, ∀ r, γ i r ∈ s) : ∀ r, concat p γ r ∈ s

theorem _root_.AnalyticOnNhd.log_norm_center_le_circleAverage {f : ℂ → ℂ} {c : ℂ} {R : ℝ}
    (hR : 0 < R) (hf : AnalyticOnNhd ℂ f (closedBall c R)) (hc : f c ≠ 0) :
    Real.log ‖f c‖ ≤ Real.circleAverage (fun z => Real.log ‖f z‖) c R

theorem _root_.ContinuousOn.measurable_comp_hirschmanLog_real {g : ℂ → ℂ}
    (hg : ContinuousOn g (HadamardThreeLines.verticalClosedStrip 0 1)) :
    Measurable (fun w : ℝ => g (log (w : ℂ) * (-I) / (π : ℂ)))

theorem tendsto_regularizedLogNorm_exp {ε : ℕ → ℝ}
    (hε : Tendsto ε atTop (𝓝 0)) (x : ℝ) :
    Tendsto (fun n => regularizedLogNorm (ε n) ((Real.exp x : ℝ) : ℂ)) atTop (𝓝 x)

theorem differentiableOn_schwarzHalfPlaneExtension (f axis : ℂ → ℂ)
    (hf : ∀ z : ℂ, 0 < z.im → DifferentiableAt ℂ f z) :
    DifferentiableOn ℂ (schwarzHalfPlaneExtension f axis) {z | z.im ≠ 0}

theorem prod_le_prod_mulVec_of_mem_doublyStochastic {B : Matrix n n ℝ}
    (hB : B ∈ doublyStochastic ℝ n) (x : n → ℝ) (hx : ∀ j, 0 < x j) :
    (∏ j, x j) ≤ ∏ i, (B *ᵥ x) i

theorem mul_midpoint_le_integral_of_convexOn {a b : ℝ} (hab : a ≤ b) {f : ℝ → ℝ}
    (hf : ContinuousOn f (Icc a b)) (hc : ConvexOn ℝ (Icc a b) f) :
    (b - a) * f ((a + b) / 2) ≤ ∫ x in a..b, f x

theorem tendsto_nat_mul_of_even_tendsto {e : ℕ → ℝ} (he : Antitone e) {b : ℝ}
    (h : Tendsto (fun n => (2*n:ℕ)*e (2*n)) atTop (𝓝 b)) :
    Tendsto (fun n : ℕ => (n:ℝ)*e n) atTop (𝓝 b)

theorem sphereChernoffParameter_mul_sub_lt_half {m x d : ℝ}
    (hm : -1 < m) (hmx : m < x) (hx : x < 1) (hd : d ≤ 1) :
    sphereChernoffParameter m x * (d-x) < 1/2

theorem log_two_mul_add_le_log_four_mul {r c D : ℝ}
    (hr : 1 ≤ r) (hc : 1 ≤ c) (hD : r * c ≤ D) :
    log (2 * (r + c)) ≤ log (4 * D)

theorem exp_one_mul_rpow_inv_two_mul_le_nine_of_log_le {d p : ℝ}
    (hd : 0 ≤ d) (hp : 0 < p) (hlog : log d ≤ p) :
