theorem scaledIIDVectorError_symmetric {b s n d : ℕ}
    (F : Frame n d) (y : YArray b s n) :
    (scaledIIDVectorError F y).transpose = scaledIIDVectorError F y

theorem sparseVectorError_symmetric {b s n d : ℕ}
    (F : Frame n d) (x : XArray b s n) :
    (sparseVectorError F x).transpose = sparseVectorError F x

@[simp] theorem flatYValue_flipYAt_same {b s : ℕ}
    (q : Fin (s * b)) (y : NestedY b s) :
    flatYValue (flipYAt q y) q = -flatYValue y q

theorem canonicalB_pos {d : ℕ} {delta eps : ℝ}
    (heps0 : 0 < eps) (heps1 : eps ≤ 1) :
    0 < sparseBlockRows d (sparseMomentOrder d delta) eps

@[simp] theorem matrixRows_apply {n d : ℕ}
    (U : Matrix (Fin n) (Fin d) ℝ) (i : Fin n) (a : Fin d) :
    matrixRows U i a = U i a

@[simp] theorem rowMatrix_matrixRows {n d : ℕ}
    (U : Matrix (Fin n) (Fin d) ℝ) :
    rowMatrix (matrixRows U) = U
